import variants from "@/data/image-variants.json";
import { assetUrl } from "./config";

/**
 * WebP copies of the supplied PNGs, generated by scripts/optimize-images.mjs into
 * /images-webp/<same folder>/<name>-<width>.webp. The original PNG is always the fallback.
 */
const VARIANTS = variants as Record<string, number[]>;

function webpPath(png: string, width: number): string {
  return png.replace(/^\/images\//, "/images-webp/").replace(/\.png$/i, `-${width}.webp`);
}

/** `srcset` for the WebP copies, or null when none were generated for this file. */
export function webpSrcSet(png: string): string | null {
  const widths = VARIANTS[png];
  if (!widths?.length) return null;
  return widths.map((w) => `${assetUrl(webpPath(png, w))} ${w}w`).join(", ");
}

/** The largest WebP copy (for zoom views), or null. */
export function largestWebp(png: string): string | null {
  const widths = VARIANTS[png];
  if (!widths?.length) return null;
  return assetUrl(webpPath(png, widths[widths.length - 1]));
}
